import{_ as e,o,c as l,a2 as t}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Κράτηση μόνο με τηλέφωνο","description":"","frontmatter":{},"headers":[],"relativePath":"el/tutorials/phone-only-booking.md","filePath":"el/tutorials/phone-only-booking.md"}'),i={name:"el/tutorials/phone-only-booking.md"};function r(n,a,s,h,p,c){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="κρατηση-μονο-με-τηλεφωνο" tabindex="-1">Κράτηση μόνο με τηλέφωνο <a class="header-anchor" href="#κρατηση-μονο-με-τηλεφωνο" aria-label="Permalink to &quot;Κράτηση μόνο με τηλέφωνο&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="σεναριο-εκπαιδευσης" tabindex="-1">Σενάριο εκπαίδευσης <a class="header-anchor" href="#σεναριο-εκπαιδευσης" aria-label="Permalink to &quot;Σενάριο εκπαίδευσης&quot;">​</a></h2><p>Ο επιβάτης ζητά τηλεφωνικά απλή μεταφορά χωρίς email. Χρησιμοποιήστε εγκεκριμένο δοκιμαστικό περιβάλλον και συνθετικά στοιχεία επιβάτη. Απαιτούνται ενεργή περιοχή, ρυθμισμένη διαδρομή και κατάλληλη κατηγορία οχήματος.</p><h2 id="βηματα" tabindex="-1">Βήματα <a class="header-anchor" href="#βηματα" aria-label="Permalink to &quot;Βήματα&quot;">​</a></h2><ol><li>Ανοίξτε τη φόρμα νέας κράτησης. Επιλέξτε ενεργή περιοχή και απλή μεταφορά.</li><li>Επιλέξτε δύο διαφορετικές τοποθεσίες από τον κατάλογο. Ορίστε ημερομηνία, ώρα, επιβάτες και αποσκευές.</li><li>Επιλέξτε κατηγορία με επαρκή χωρητικότητα. Καταχωρίστε συνθετικό όνομα και τηλέφωνο. Αφήστε το <strong>Email (Optional)</strong> κενό.</li><li>Ελέγξτε την τιμή και περιμένετε την επαλήθευση από τον διακομιστή στην πιστοποιημένη λειτουργία. Αν απαιτείται χειροκίνητη προσφορά, ακολουθήστε την αντίστοιχη διαδικασία.</li><li>Υποβάλετε μία φορά και εντοπίστε τον κωδικό στις κρατήσεις. Ελέγξτε διαδρομή, ώρα, τηλέφωνο και κενό email.</li></ol><h2 id="ελεγχος-αποτελεσματος" tabindex="-1">Έλεγχος αποτελέσματος <a class="header-anchor" href="#ελεγχος-αποτελεσματος" aria-label="Permalink to &quot;Έλεγχος αποτελέσματος&quot;">​</a></h2><p>Η απουσία email από μόνη της δεν πρέπει να εμποδίζει την κράτηση. Αν το αποτέλεσμα είναι αβέβαιο, αναζητήστε την κράτηση πριν δημιουργήσετε άλλη. Μην επινοείτε email.</p><p>Δείτε <a href="/el/plus/create-reservation.html">Δημιουργία κράτησης</a> και <a href="/el/plus/passenger-information.html">Στοιχεία επιβάτη</a>.</p>',9)])])}const _=e(i,[["render",r]]);export{m as __pageData,_ as default};
